var _markdown = "\n\n`sa` · 扩展 `SAMPFUNCS` · 仅 SA-MP；需 SAMPFUNCS\n\n共 4 条。调用见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 加载 / 释放 / 绘制 [#加载--释放--绘制]\n\n<Opcode id=\"0B71\" name=\"SF_D3D_LOAD_TEXTURE_FROM_FILE\" member=\"SfD3DTexture.Load\">\n  从文件（图片或 txd）加载为 D3DTexture 对象。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0B71 SF_D3D_LOAD_TEXTURE_FROM_FILE\n      in: filePath\n      out: handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local handle = sfD3dLoadTextureFromFile(filePath)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = SfD3DTexture.Load(filePath)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0B72\" name=\"SF_D3D_RELEASE_TEXTURE\" member=\"SfD3DTexture.Release\">\n  释放 D3DTexture 对象内存。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0B72 SF_D3D_RELEASE_TEXTURE\n      in: self\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if sfD3dReleaseTexture(self) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (SfD3DTexture.release(self)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0B73\" name=\"SF_D3D_DRAW_TEXTURE\" member=\"SfD3DTexture.Draw\">\n  在屏幕上绘制该纹理。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0B73 SF_D3D_DRAW_TEXTURE\n      in: self, coordX, coordY, width, height, heading, contrast\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      sfD3dDrawTexture(self, coordX, coordY, width, height, heading, contrast)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      SfD3DTexture.draw(self, coordX, coordY, width, height, heading, contrast)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0C8C\" name=\"SF_D3D_LOAD_TEXTURE_FROM_FILE_IN_MEMORY\" member=\"SfD3DTexture.LoadTextureFromFileMemory\">\n  从内存缓冲中的文件数据加载纹理。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C8C SF_D3D_LOAD_TEXTURE_FROM_FILE_IN_MEMORY\n      in: buffer, bufferSize\n      out: handle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local handle = sfD3dLoadTextureFromFileInMemory(buffer, bufferSize)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = SfD3DTexture.LoadTextureFromFileMemory(buffer, bufferSize)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
